CREATE TABLE public.crm_memberships(user_id uuid PRIMARY KEY, role text NOT NULL CHECK(role IN ('sales','support','BDE','BDM')), manager_id uuid, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.crm_memberships TO authenticated; GRANT ALL ON public.crm_memberships TO service_role;
ALTER TABLE public.crm_memberships ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.crm_role() RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN public.has_role(auth.uid(),'admin') THEN 'admin' ELSE (SELECT role FROM public.crm_memberships WHERE user_id=auth.uid() AND active) END $$;
CREATE OR REPLACE FUNCTION public.crm_can_access(_owner uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.crm_memberships me WHERE me.user_id=auth.uid() AND me.active AND (me.user_id=_owner OR (me.role='BDM' AND EXISTS(SELECT 1 FROM public.crm_memberships member WHERE member.user_id=_owner AND member.manager_id=me.user_id AND member.active)))) $$;
REVOKE ALL ON FUNCTION public.crm_role(),public.crm_can_access(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.crm_role(),public.crm_can_access(uuid) TO authenticated;
CREATE POLICY crm_members_read ON public.crm_memberships FOR SELECT TO authenticated USING(public.crm_can_access(user_id));
CREATE POLICY crm_members_admin ON public.crm_memberships FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.crm_employee_profiles(user_id uuid PRIMARY KEY, employee_code text NOT NULL UNIQUE, full_name text NOT NULL, phone text NOT NULL DEFAULT '', designation text NOT NULL DEFAULT '', photo_url text, joining_date date NOT NULL DEFAULT CURRENT_DATE);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.crm_employee_profiles TO authenticated; GRANT ALL ON public.crm_employee_profiles TO service_role;
ALTER TABLE public.crm_employee_profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY crm_profiles_read ON public.crm_employee_profiles FOR SELECT TO authenticated USING(public.crm_can_access(user_id));
CREATE POLICY crm_profiles_admin ON public.crm_employee_profiles FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.crm_customers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_code text NOT NULL UNIQUE DEFAULT ('CUS-'||upper(substr(gen_random_uuid()::text,1,8))), full_name text NOT NULL, email text NOT NULL DEFAULT '', phone text NOT NULL DEFAULT '', company text NOT NULL DEFAULT '', acknowledgement text, owner_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.crm_customers TO authenticated; GRANT ALL ON public.crm_customers TO service_role;
ALTER TABLE public.crm_customers ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.crm_leads(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid NOT NULL REFERENCES public.crm_customers(id), title text NOT NULL, stage text NOT NULL DEFAULT 'new' CHECK(stage IN ('new','contacted','qualified','proposal','won','lost')), amount numeric NOT NULL DEFAULT 0 CHECK(amount>=0), source text NOT NULL DEFAULT 'manual', source_id uuid, owner_id uuid NOT NULL, next_follow_up date, notes text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(source,source_id));
GRANT SELECT,INSERT,UPDATE ON public.crm_leads TO authenticated; GRANT ALL ON public.crm_leads TO service_role;
ALTER TABLE public.crm_leads ENABLE ROW LEVEL SECURITY;
CREATE POLICY crm_leads_read ON public.crm_leads FOR SELECT TO authenticated USING(public.crm_can_access(owner_id) AND public.crm_role()<>'support');
CREATE POLICY crm_leads_write ON public.crm_leads FOR ALL TO authenticated USING(public.crm_can_access(owner_id) AND public.crm_role()<>'support') WITH CHECK(public.crm_can_access(owner_id) AND public.crm_role()<>'support');
CREATE TABLE public.crm_tasks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, owner_id uuid NOT NULL, customer_id uuid REFERENCES public.crm_customers(id), due_date date NOT NULL, status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','done')), priority text NOT NULL DEFAULT 'normal' CHECK(priority IN ('normal','high','urgent')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.crm_tasks TO authenticated; GRANT ALL ON public.crm_tasks TO service_role;
ALTER TABLE public.crm_tasks ENABLE ROW LEVEL SECURITY;
CREATE POLICY crm_tasks_access ON public.crm_tasks FOR ALL TO authenticated USING(public.crm_can_access(owner_id)) WITH CHECK(public.crm_can_access(owner_id));
CREATE TABLE public.crm_tickets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), ticket_code text NOT NULL UNIQUE DEFAULT ('TKT-'||upper(substr(gen_random_uuid()::text,1,8))), customer_id uuid NOT NULL REFERENCES public.crm_customers(id), owner_id uuid NOT NULL, subject text NOT NULL, description text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','in_progress','resolved')), priority text NOT NULL DEFAULT 'normal' CHECK(priority IN ('normal','high','urgent')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.crm_tickets TO authenticated; GRANT ALL ON public.crm_tickets TO service_role;
ALTER TABLE public.crm_tickets ENABLE ROW LEVEL SECURITY;
CREATE POLICY crm_tickets_access ON public.crm_tickets FOR ALL TO authenticated USING(public.crm_can_access(owner_id) AND public.crm_role() IN ('admin','support','BDM')) WITH CHECK(public.crm_can_access(owner_id) AND public.crm_role() IN ('admin','support','BDM'));
CREATE POLICY crm_customers_read ON public.crm_customers FOR SELECT TO authenticated USING(public.crm_can_access(owner_id) OR (public.crm_role()='support' AND EXISTS(SELECT 1 FROM public.crm_tickets t WHERE t.customer_id=crm_customers.id AND t.owner_id=auth.uid())));
CREATE POLICY crm_customers_write ON public.crm_customers FOR INSERT TO authenticated WITH CHECK(public.crm_can_access(owner_id));
CREATE POLICY crm_customers_update ON public.crm_customers FOR UPDATE TO authenticated USING(public.crm_can_access(owner_id)) WITH CHECK(public.crm_can_access(owner_id));
CREATE TABLE public.crm_activities(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL, actor_id uuid NOT NULL DEFAULT auth.uid(), lead_id uuid REFERENCES public.crm_leads(id), ticket_id uuid REFERENCES public.crm_tickets(id), kind text NOT NULL DEFAULT 'note' CHECK(kind IN ('note','call','email','meeting','stage_change','ticket_change')), body text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.crm_activities TO authenticated; GRANT ALL ON public.crm_activities TO service_role;
ALTER TABLE public.crm_activities ENABLE ROW LEVEL SECURITY;
CREATE POLICY crm_activity_read ON public.crm_activities FOR SELECT TO authenticated USING(public.crm_can_access(owner_id));
CREATE POLICY crm_activity_insert ON public.crm_activities FOR INSERT TO authenticated WITH CHECK(public.crm_can_access(owner_id) AND actor_id=auth.uid());
CREATE TABLE public.crm_targets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL, month date NOT NULL, revenue_target numeric NOT NULL DEFAULT 0 CHECK(revenue_target>=0), wins_target integer NOT NULL DEFAULT 0 CHECK(wins_target>=0), calls_target integer NOT NULL DEFAULT 0 CHECK(calls_target>=0), UNIQUE(owner_id,month));
GRANT SELECT,INSERT,UPDATE ON public.crm_targets TO authenticated; GRANT ALL ON public.crm_targets TO service_role;
ALTER TABLE public.crm_targets ENABLE ROW LEVEL SECURITY;
CREATE POLICY crm_targets_read ON public.crm_targets FOR SELECT TO authenticated USING(public.crm_can_access(owner_id));
CREATE POLICY crm_targets_manage ON public.crm_targets FOR ALL TO authenticated USING(public.crm_can_access(owner_id) AND public.crm_role() IN ('admin','BDM')) WITH CHECK(public.crm_can_access(owner_id) AND public.crm_role() IN ('admin','BDM'));
CREATE OR REPLACE FUNCTION public.crm_record_changes() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN NEW.updated_at=now(); IF TG_TABLE_NAME='crm_leads' AND NEW.stage IS DISTINCT FROM OLD.stage THEN INSERT INTO public.crm_activities(owner_id,actor_id,lead_id,kind,body) VALUES(NEW.owner_id,auth.uid(),NEW.id,'stage_change',OLD.stage||' → '||NEW.stage); ELSIF TG_TABLE_NAME='crm_tickets' AND NEW.status IS DISTINCT FROM OLD.status THEN INSERT INTO public.crm_activities(owner_id,actor_id,ticket_id,kind,body) VALUES(NEW.owner_id,auth.uid(),NEW.id,'ticket_change',OLD.status||' → '||NEW.status); END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.crm_record_changes() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER crm_lead_changes BEFORE UPDATE ON public.crm_leads FOR EACH ROW EXECUTE FUNCTION public.crm_record_changes();
CREATE TRIGGER crm_ticket_changes BEFORE UPDATE ON public.crm_tickets FOR EACH ROW EXECUTE FUNCTION public.crm_record_changes();
CREATE INDEX crm_leads_owner ON public.crm_leads(owner_id); CREATE INDEX crm_customers_ack ON public.crm_customers(acknowledgement); CREATE INDEX crm_tasks_owner_due ON public.crm_tasks(owner_id,due_date);